import json,time,urllib.request,urllib.error
from pathlib import Path
import argparse
p=argparse.ArgumentParser();p.add_argument('--url',required=True);p.add_argument('--fixture-dir',required=True);a=p.parse_args();fixture=Path(a.fixture_dir)
base=a.url;session=json.load(urllib.request.urlopen(base+'/api/session'))
assert session.get('environment')=='test','Refusing to modify real user Gateway settings'
token=session['token'];checks=[]
def call(path,body=None,expected=200,token_value=token):
 time.sleep(.3)
 req=urllib.request.Request(base+path,data=json.dumps(body).encode() if body is not None else None,headers={'X-Reach-Token':token_value,'Content-Type':'application/json'})
 try:
  with urllib.request.urlopen(req,timeout=30) as r:status=r.status;data=json.load(r)
 except urllib.error.HTTPError as e:status=e.code;data=json.loads(e.read()) if e.code!=403 else {}
 assert status==expected,(path,status,data)
 return data
def check(ok,label):assert ok,label;checks.append(label)
check('ca_pem' not in call('/api/ibkr/settings'),'public settings omit certificate')
check(call('/api/ibkr/settings')['login_url'] is None,'test runtime cannot open real login')
call('/api/ibkr/settings',{'port':5000},400);checks.append('test runtime blocks real Gateway port')
call('/api/ibkr/settings',{'port':5001,'api_key':'fake'},400);checks.append('API keys rejected for Gateway')
call('/api/ibkr/settings',{'port':5001,'url':'https://external.test'},400);checks.append('external targets rejected')
call('/api/ibkr/settings',{'port':5001},403,token_value='bad');checks.append('write token enforced')
call('/api/ibkr/settings',{'port':5001});call('/api/ibkr/status',{},400);checks.append('untrusted TLS rejected')
cert=Path(fixture/'mock-cert.pem').read_text();call('/api/ibkr/settings',{'port':5001,'ca_pem':cert})
s=call('/api/ibkr/status',{});check(s=={'authenticated':True,'competing':False,'connected':True},'status projection excludes hardware/account details')
conn=call('/api/ibkr/connection',{});check(conn['sso_valid'] and conn['authenticated'],'dual session verification')
check('PRIVATE-SSO' not in json.dumps(conn) and 'USER_ID' not in conn,'SSO identity excluded')
Path(fixture/'mock-mode').write_text('readonly');conn=call('/api/ibkr/connection',{});check(conn['sso_valid'] and not conn['authenticated'],'read-only login distinct from brokerage authentication')
check(call('/api/ibkr/connect-market',{})=={'requested':True,'authenticated':True,'competing':False},'manual market initialization uses fixed non-competing payload')
Path(fixture/'mock-mode').write_text('initializing');pending=call('/api/ibkr/connect-market',{});check(pending['requested'] and not pending['authenticated'],'incomplete init is pending rather than success')
conn=call('/api/ibkr/connection',{});check(not conn['market_ready'],'missing account bootstrap cannot report market ready')
Path(fixture/'mock-mode').write_text('ok');time.sleep(5.1);conn=call('/api/ibkr/connection',{});check(conn['market_ready'] and not conn['initializing'],'bounded account bootstrap completes asynchronous initialization')
rows=call('/api/ibkr/search',{'query':'Apple & AAPL','by_name':True});check(rows[0]['conid']=='265598' and 'secret' not in rows[0],'encoded search with public projection')
detail=call('/api/ibkr/detail',{'conid':'265598'});check(detail['currency']=='USD' and detail['instrument_type']=='STK','official snake_case detail shape supported')
call('/api/ibkr/detail',{'conid':'../orders'},400);checks.append('path injection rejected')
call('/api/ibkr/snapshot',{'conid':'265598'},400);checks.append('market data preparation required')
Path(fixture/'mock-mode').write_text('warming');failure=call('/api/ibkr/prepare',{},400);check('行情会话' in failure['error'] and 'PRIVATE-ERROR-IDENTITY' not in failure['error'],'warming error explains session state without leaking broker body')
Path(fixture/'mock-mode').write_text('emptyaccounts');call('/api/ibkr/prepare',{},400);checks.append('empty market accounts cannot mark session prepared')
call('/api/ibkr/snapshot',{'conid':'265598'},400);checks.append('failed preparation keeps snapshots blocked')
Path(fixture/'mock-mode').write_text('ok')
check(call('/api/ibkr/prepare',{})=={'ok':True},'account prerequisite executed without returning accounts')
snap=call('/api/ibkr/snapshot',{'conid':'265598'});check(snap['availability']=='延迟' and snap['fields'][0]['value']=='C193.18','snapshot prefixes and delay preserved')
check('PRIVATE-POSITION' not in json.dumps(snap),'position data excluded')
h=call('/api/ibkr/history',{'conid':'265598'});check(len(h['bars'])==1 and h['bars'][0]['c']==193,'historical daily preview')
call('/api/ibkr/margin',{'account':'TEST_ONLY'},400);checks.append('margin account must be locally discovered')
accounts=call('/api/ibkr/accounts',{});check(accounts==[{'id':'TEST_ONLY','currency':'USD','tradingType':'PM'}],'account list projects only required fields')
margin=call('/api/ibkr/margin',{'account':'TEST_ONLY'});check(margin['status']=='low-buffer' and margin['liquidity_ratio']==.05,'broker margin totals normalized')
call('/api/ibkr/margin',{'account':'TEST_ONLY'},400);checks.append('margin pacing enforced')
call('/api/ibkr/margin',{'account':'../orders'},400);checks.append('margin account path injection rejected')
Path(fixture/'mock-mode').write_text('pending');check(call('/api/ibkr/snapshot',{'conid':'265598'})['pending'],'preflight empty values explicitly pending')
Path(fixture/'mock-mode').write_text('loggedout');check(not call('/api/ibkr/status',{})['authenticated'],'logged-out auth state')
Path(fixture/'mock-mode').write_text('unauthorized');call('/api/ibkr/search',{'query':'AAPL'},400);checks.append('expired session handled')
Path(fixture/'mock-mode').write_text('quota');call('/api/ibkr/search',{'query':'AAPL'},400);checks.append('quota error handled')
Path(fixture/'mock-mode').write_text('logoutfail')
call('/api/ibkr/logout',{},400);checks.append('unconfirmed remote logout reports failure')
call('/api/ibkr/snapshot',{'conid':'265598'},400);checks.append('failed logout still clears local preparation')
Path(fixture/'mock-mode').write_text('ok')
check(call('/api/ibkr/logout',{})['logged_out'],'remote logout confirmed')
check(not call('/api/ibkr/status',{})['authenticated'],'session no longer authenticated after logout')
call('/api/ibkr/margin',{'account':'TEST_ONLY'},400);checks.append('logout invalidates discovered margin accounts')
call('/api/ibkr/snapshot',{'conid':'265598'},400);checks.append('logout clears market preparation')
conn=call('/api/ibkr/connection',{});check(conn['sso_valid'] is None,'logout invalidates SSO cache without breaking upstream pacing')
check(all(not values for values in call('/api/export').values()),'IBKR previews never mutate existing ledger or daily quotes')
requests=[json.loads(x) for x in Path(fixture/'mock-requests.jsonl').read_text().splitlines()]
check(any('Apple%20%26%20AAPL' in r['path'] for r in requests),'query URL encoding verified by server')
check(sum('/sso/validate' in r['path'] for r in requests)==1,'SSO validation limited to once per minute')
check(not any('/orders' in r['path'] or '/regsnapshot' in r['path'] for r in requests),'no trading or regulatory snapshot requests')
report={'ok':True,'checks':len(checks),'passed':checks,'scope':'Isolated synthetic HTTPS gateway with trusted test certificate; no real IBKR session'}
Path(fixture/'test-report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2));print(json.dumps(report,ensure_ascii=False,indent=2))
